const WORKFLOW_TOOLS=[
 {kind:'qc',name:'FastQC Quality Control',short:'FastQC',version:'v0.11.9',desc:'Read quality assessment',cpu:4,ram:8,image:'biocontainers/fastqc:v0.11.9_cv8',accent:'#4E7898'},
 {kind:'align',name:'BWA-MEM Alignment',short:'BWA-MEM',version:'v0.7.17',desc:'Reference genome alignment',cpu:16,ram:32,image:'biocontainers/bwa:v0.7.17_cv1',accent:'#2F8C83'},
 {kind:'variant',name:'GATK HaplotypeCaller',short:'GATK4 Haplotype',version:'v4.2.5',desc:'Germline variant calling',cpu:8,ram:16,image:'broadinstitute/gatk:4.2.5.0',accent:'#6D719C'}
];
function workflowSelectedNode(){return state.workflowNodes.find(n=>n.id===state.workflowSelected)||state.workflowNodes[0]}
function workflowKindMeta(kind){return {input:['FASTQ Input','#557B8F'],qc:['Quality Control','#4E7898'],align:['Sequence Alignment','#2F8C83'],variant:['Variant Detection','#6D719C']}[kind]||['Workflow Node','#1E6A7A']}
function workflowCode(node=workflowSelectedNode()){
 if(!node)return '# Select a node to inspect generated code';
 if(node.kind==='input')return `// Input dataset\nChannel.fromPath('data/*.fastq.gz')\n  .set { reads_ch }`;
 const proc=node.kind==='qc'?'FASTQC':node.kind==='align'?'BWA_ALIGN':'GATK_HAPLOTYPE';
 const body=node.kind==='qc'?'fastqc -t '+node.cpu+' $reads -o results/qc':node.kind==='align'?'bwa mem -t '+node.cpu+' hg38.fa $reads > aligned.sam':'gatk HaplotypeCaller -I input.bam -R hg38.fa -O raw_variants.vcf';
 return `process ${proc} {\n  tag "${node.name}"\n  cpus ${node.cpu}\n  memory '${node.ram} GB'\n  container '${node.image}'\n\n  input:\n  path input_file\n\n  script:\n  \"\"\"\n  ${body}\n  \"\"\"\n}`;
}
function workflowFullNextflow(){return `nextflow.enable.dsl=2\n\nworkflow {\n  // TriOmeFlow · BioForge offline orchestration preview\n  // Replace demo channels with validated project inputs before production use.\n}\n\n${state.workflowNodes.map(n=>workflowCode(n)).join('\n\n')}`}
function workflowConnections(){const nodes=state.workflowNodes;return nodes.slice(0,-1).map((n,i)=>{const next=nodes[i+1],x1=n.x??50,x2=next.x??50,y1=n.y+78,y2=next.y;return `<path class="workflow-edge ${state.workflowStatus==='running'?'active':''}" d="M ${x1} ${y1} C ${x1} ${y1+18}, ${x2} ${y2-18}, ${x2} ${y2}"/>`}).join('')}
function workflowNodeHtml(n){const [kind,color]=workflowKindMeta(n.kind);return `<div class="workflow-node ${state.workflowSelected===n.id?'selected':''} ${n.status==='running'?'running':n.status==='success'?'success':''}" data-wf-node="${n.id}" style="left:${n.x??50}%;top:${n.y}px"><div class="wf-head"><span class="wf-kind"><i class="tool-accent" style="background:${color}"></i>${kind}</span><span class="wf-status ${n.status}"></span></div><div class="wf-title">${esc(n.name)}</div><div class="wf-meta"><span>${esc(n.version)}</span><span class="mono">${n.cpu} CPU · ${n.ram} GB</span></div><div class="wf-meta"><span>${esc(n.subtitle||'Local workflow node')}</span><span>${n.status}</span></div></div>`}
function workflowToolbox(){return `<div>${WORKFLOW_TOOLS.map(t=>`<div class="workflow-tool" data-add-workflow="${t.kind}"><div class="tool-top"><h4><i class="tool-accent" style="background:${t.accent}"></i>${t.short}</h4><span class="pipeline-pill">${t.version}</span></div><p>${t.desc}</p></div>`).join('')}<div class="workflow-note">Pipeline execution is simulated locally; no Docker, Kubernetes or external cluster is contacted.</div></div>`}
function workflowInspector(){const n=workflowSelectedNode();if(!n)return `<div class="muted small">No node selected.</div>`;return `<div class="workflow-inspector"><div class="field"><label>Selected node</label><input id="wfNodeName" value="${esc(n.name)}"></div><div class="field"><label>Container image</label><input id="wfNodeImage" class="mono" value="${esc(n.image)}"></div><div class="grid grid-2" style="gap:8px"><div class="field"><label>CPU cores</label><select id="wfNodeCpu">${[2,4,8,16,32].map(v=>`<option ${n.cpu===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Memory</label><select id="wfNodeRam">${[4,8,16,32,64].map(v=>`<option ${n.ram===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Generated Nextflow</label><pre class="workflow-code">${esc(workflowCode(n))}</pre></div><div>${badge('TRIOMEFLOW DEMO','demo')} ${badge('STATIC CODE PREVIEW','')}</div></div>`}
function workflowTerminal(){const logs=state.workflowLogs||[];return `<div class="workflow-terminal"><div class="workflow-terminal-head"><span>Executor Terminal</span><span>${state.workflowStatus==='running'?'Running':state.workflowStatus==='success'?'Completed':'Ready'}</span></div><div class="workflow-terminal-body" id="workflowTerminal">${logs.map(l=>`<div class="workflow-log ${l.type||''}">[${l.time||'local'}] ${esc(state.lang==='cn'?tr(l.text):l.text)}</div>`).join('')}</div></div>`}
function renderWorkflow(){const totalCpu=state.workflowNodes.reduce((a,n)=>a+n.cpu,0),totalRam=state.workflowNodes.reduce((a,n)=>a+n.ram,0);const head=pageHeader('BioForge Workflow Studio','Compose, inspect and simulate reproducible bioinformatics workflows inside the TriOmeFlow workspace.','在 TriOmeFlow 工作空间中编排、检查并模拟可复现的生物信息流程。',[badge('WORKFLOW ORCHESTRATION',''),badge('NEXTFLOW DSL2',''),badge('OFFLINE SIMULATION','live'),badge('DETERMINISTIC','live')],btn('Reset Workflow','resetWorkflow')+btn('Export Nextflow','exportWorkflow')+btn('Run Pipeline','runWorkflow','primary'));
 const kpis=`<div class="workflow-kpis">${kpi('Modules',String(state.workflowNodes.length),'Current DAG nodes','blue')}${kpi('Configured CPU',String(totalCpu),'Total requested cores','probiotic')}${kpi('Configured Memory',`${totalRam} GB`,'Total requested memory','host')}${kpi('Pipeline status',state.workflowStatus==='running'?'Running':state.workflowStatus==='success'?'Completed':'Ready','Local orchestration simulation','virus')}</div>`;
 const canvas=`<div class="workflow-canvas" id="workflowCanvas"><div class="workflow-canvas-toolbar"><span class="workflow-chip">WGS Variant Calling Pipeline</span><span class="workflow-chip">AUTO LAYOUT · LOCAL DEMO</span></div><svg class="workflow-connections" viewBox="0 0 100 520" preserveAspectRatio="none"><defs><marker id="wfArrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3 0 6Z" fill="#9AB2BF"/></marker></defs>${workflowConnections().replaceAll('/>',' marker-end="url(#wfArrow)"/>')}</svg>${state.workflowNodes.map(workflowNodeHtml).join('')}</div>`;
 return `<div class="page workflow-page">${head}${kpis}<div class="workflow-layout"><div class="sticky-side">${panel('Workflow Modules','Click to add reusable bioinformatics components.',workflowToolbox())}</div>${panel('Pipeline Canvas','Drag nodes to arrange the workflow. Select any node to inspect and configure it.',canvas)}<div class="sticky-side">${panel('Node Parameters','Configuration updates the generated Nextflow preview locally.',workflowInspector())}</div></div>${workflowTerminal()}</div>`}
function workflowLog(text,type='info'){state.workflowLogs=[...(state.workflowLogs||[]),{time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}),text,type}].slice(-40)}
function addWorkflowNode(kind){const t=WORKFLOW_TOOLS.find(x=>x.kind===kind);if(!t)return;const seq=state.workflowSeq||1,id=`wf-${kind}-${seq}`;state.workflowSeq=seq+1;const maxY=Math.max(...state.workflowNodes.map(n=>n.y),40);state.workflowNodes=[...state.workflowNodes,{id,kind,name:t.name,version:t.version,subtitle:t.desc,cpu:t.cpu,ram:t.ram,image:t.image,status:'pending',x:50,y:Math.min(maxY+108,410)}];state.workflowSelected=id;workflowLog(`Module added: ${t.short}`,'info');persist();renderApp();toast('Module added','success')}
function updateWorkflowSelected(patch){state.workflowNodes=state.workflowNodes.map(n=>n.id===state.workflowSelected?{...n,...patch}:n);persist();renderApp()}
function resetWorkflow(){state.workflowNodes=structuredClone(DEFAULT_STATE.workflowNodes);state.workflowSelected='wf-bwa';state.workflowLogs=structuredClone(DEFAULT_STATE.workflowLogs);state.workflowStatus='ready';state.workflowSeq=1;persist();renderApp();toast('Workflow reset','success')}
function exportWorkflow(){downloadBlob('triomeflow-bioforge-workflow.nf',workflowFullNextflow(),'text/plain')}
function runWorkflowPipeline(){if(state.workflowStatus==='running')return;state.workflowStatus='running';state.workflowNodes=state.workflowNodes.map(n=>({...n,status:'pending'}));state.workflowLogs=[];workflowLog('Pipeline orchestration simulation started.','info');persist();renderApp();const ids=state.workflowNodes.map(n=>n.id);let i=0;const step=()=>{if(i>=ids.length){state.workflowStatus='success';workflowLog('Pipeline simulation completed · deterministic demo outputs ready.','success');registerRun('WF','Workflow Studio','Demo','Pipeline orchestration simulation',`${Math.max(1,ids.length)*520} ms`);persist();renderApp();toast('Pipeline simulation completed','success');return}const id=ids[i],node=state.workflowNodes.find(n=>n.id===id);state.workflowNodes=state.workflowNodes.map(n=>({...n,status:n.id===id?'running':n.status}));workflowLog(`Task ${i+1}/${ids.length}: ${node.name} started.`,'info');persist();renderApp();setTimeout(()=>{state.workflowNodes=state.workflowNodes.map(n=>({...n,status:n.id===id?'success':n.status}));workflowLog(`${node.name} completed.`,'success');persist();renderApp();i++;setTimeout(step,180)},340)};setTimeout(step,250)}
function bindWorkflowDrag(){document.querySelectorAll('.workflow-node').forEach(el=>{el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const id=el.dataset.wfNode;state.workflowSelected=id;const canvas=document.getElementById('workflowCanvas');const node=state.workflowNodes.find(n=>n.id===id),startY=e.clientY,startX=e.clientX,origY=node?.y||0,origX=node?.x??50;el.setPointerCapture?.(e.pointerId);const move=ev=>{const rect=canvas.getBoundingClientRect();const y=Math.max(42,Math.min(420,origY+(ev.clientY-startY)));const x=Math.max(20,Math.min(80,origX+(ev.clientX-startX)/Math.max(rect.width,1)*100));el.style.top=y+'px';el.style.left=x+'%';const n=state.workflowNodes.find(n=>n.id===id);if(n){n.y=y;n.x=x}};const up=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);persist();renderApp()};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up,{once:true})})})}

function candidateCards(){const ranked=rankCandidates([REFERENCE_CANDIDATE,...CANDIDATES],state.weights);const ref=ranked.find(c=>c.reference);const top=[ref,...ranked.filter(c=>!c.reference).slice(0,5)];const paretoIds=new Set(paretoFront([REFERENCE_CANDIDATE,...CANDIDATES]).map(x=>x.id));return top.map((c,i)=>`<div class="candidate-card ${state.selectedCandidate===c.id?'selected':''}" data-candidate="${c.id}"><div class="candidate-top"><div><div class="rank">${String(i+1).padStart(2,'0')} ${c.reference?'· REFERENCE':''}</div><div class="candidate-id">${c.id}</div></div><div class="score mono">${(c.score*100).toFixed(1)}</div></div><div class="metric-mini"><span>Aff<b>${c.affinity.toFixed(2)}</b></span><span>Brd<b>${c.breadth.toFixed(2)}</b></span><span>Stb<b>${c.stability.toFixed(2)}</b></span><span>Sec<b>${c.secretion.toFixed(2)}</b></span></div><div style="margin-top:7px;display:flex;align-items:center;justify-content:space-between;gap:6px"><span>${c.reference?badge('FLUBLOCKERS','source'):badge('DEMO','demo')} ${paretoIds.has(c.id)?badge('PARETO',''):''}</span>${c.reference?'':`<button class="btn small ${state.shortlist.includes(c.id)?'':'primary'}" data-shortlist="${c.id}">${state.shortlist.includes(c.id)?'Remove':'Shortlist'}</button>`}</div></div>`).join('')}
function objectiveControls(){return `<div><div class="eyebrow">DESIGN SETUP</div><div class="meta-grid"><dt>Target</dt><dd>Influenza HA</dd><dt>Subtype</dt><dd>H1N1</dd><dt>Structure template</dt><dd class="mono">PDB 1RUZ</dd><dt>Antibody template</dt><dd>MEDI8852 scFv</dd></div><div class="divider"></div><div class="eyebrow">DESIGN OBJECTIVES</div>${Object.entries(state.weights).map(([k,v])=>`<div class="objective"><div class="objective-head"><strong>${({affinity:'Binding Affinity',breadth:'Broad-spectrum Potential',stability:'Structural Stability',secretion:'Secretion Feasibility'})[k]}</strong><span class="mono">${v.toFixed(0)}%</span></div><input class="objective-slider" data-weight="${k}" type="range" min="0" max="70" step="1" value="${v}"></div>`).join('')}<div class="tiny muted">Weights are normalized to 100% · ranking is live.</div><div style="margin-top:12px">${btn('Re-rank Candidates','rerank','primary')}</div></div>`}
function paretoPlot(){const all=[REFERENCE_CANDIDATE,...CANDIDATES],front=new Set(paretoFront(all).map(x=>x.id));return `<div class="pareto"><div class="pareto-axis x"></div><div class="pareto-axis y"></div><span class="pareto-label axis-x-label">Affinity →</span><span class="pareto-label axis-y-label">Stability →</span>${all.map(c=>{const x=45+(c.affinity-.75)/.22*520;const y=250-(c.stability-.80)/.18*210;return `<span class="pareto-point ${front.has(c.id)?'frontier':''}" data-candidate="${c.id}" style="left:${x}px;top:${y}px" title="${c.id} · affinity ${c.affinity} · stability ${c.stability}"></span>`}).join('')}</div><div class="tiny muted">Purple = Pareto-optimal · metrics are deterministic synthetic design inputs except MEDI8852-WT reference context.</div>`}
function comparisonTable(){const selected=[REFERENCE_CANDIDATE,...CANDIDATES].filter(c=>c.reference||state.shortlist.includes(c.id)).slice(0,3);return `<table class="sci-table"><thead><tr><th>Metric</th>${selected.map(c=>`<th>${c.id}</th>`).join('')}</tr></thead><tbody>${['affinity','breadth','stability','secretion'].map(m=>`<tr><td>${m[0].toUpperCase()+m.slice(1)}</td>${selected.map(c=>`<td class="mono">${c[m].toFixed(2)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="tiny muted" style="margin-top:10px">Comparison includes reference + shortlisted demo candidates.</div>`}
function antibodyBottom(){const tabs=['summary','pareto','interface','compare'];const labels={summary:'Summary',pareto:'Pareto Front',interface:'Interface',compare:'Compare'};let body='';if(state.antibodyTab==='summary'){
  const occ=langmuirOccupancy(state.langmuirConcentration,6.8);body=`<div class="grid grid-4">${kpi('Binding Free Energy','≈ −11.4','kcal/mol · PRODIGY','host')}${kpi('Dissociation Constant','≈ 6.8','nM · predicted','blue')}${kpi('Binding Region','HA stem','ZDOCK source summary','virus')}${kpi('Structural Assessment','Favorable','PyMOL / iMODS summary','probiotic')}</div><div class="grid grid-2" style="margin-top:14px"><div class="panel" style="box-shadow:none"><div class="panel-body"><div class="eyebrow">METHOD CHAIN</div><p class="small">Sequence → Swiss-Model → ZDOCK → PyMOL/iMODS → PRODIGY</p>${badge('FLUBLOCKERS SOURCE','source')}</div></div><div class="panel" style="box-shadow:none"><div class="panel-body"><div class="eyebrow">BINDING OCCUPANCY · LIVE</div><div class="objective-head"><strong>Antibody concentration</strong><span class="mono">${state.langmuirConcentration} nM</span></div><input id="langmuirSlider" type="range" min="0" max="50" step="1" value="${state.langmuirConcentration}" style="width:100%"><div style="margin-top:8px"><b class="mono" style="font-size:22px">${(occ*100).toFixed(1)}%</b> <span class="tiny muted">estimated occupancy · Kd 6.8 nM</span></div></div></div></div>`;
  } else if(state.antibodyTab==='pareto') body=paretoPlot(); else if(state.antibodyTab==='interface') body=`<div class="grid grid-2"><div class="panel" style="box-shadow:none"><div class="panel-body"><div class="eyebrow">INTERFACE SUMMARY</div><div class="meta-grid"><dt>Target region</dt><dd>HA stem</dd><dt>Predicted ΔG</dt><dd>≈ −11.4 kcal/mol</dd><dt>Predicted Kd</dt><dd>≈ 6.8 nM</dd><dt>Docking method</dt><dd>ZDOCK</dd><dt>Residue contacts</dt><dd>Not supplied</dd></div></div></div><div class="panel" style="box-shadow:none"><div class="panel-body"><div class="eyebrow">SCIENTIFIC BOUNDARY</div><p class="small muted">No validated MEDI8852–HA docking PDB or residue-contact list was supplied. The viewport remains an explicitly labeled reference visualization.</p>${badge('REFERENCE PLACEHOLDER','warning')}</div></div></div>`; else body=comparisonTable();
  return `<div class="tabbar">${tabs.map(t=>`<button class="tab ${state.antibodyTab===t?'active':''}" data-antibody-tab="${t}">${labels[t]}</button>`).join('')}</div><div style="margin-top:14px">${body}</div>`;
}
function renderAntibody(){
  const ref=REFERENCE_STRUCTURES.medi8852H5;
  const head=pageHeader('Antibody Design Studio','Inspect molecular interactions and explore multi-objective scFv design candidates against influenza HA.','以 MEDI8852 scFv–HA 为参考，查看结构与结合界面，并探索多目标设计候选。',[badge('MEDI8852 TEMPLATE','source'),badge('STRUCTURAL REFERENCE',''),badge('OFFLINE','live'),badge('SYNTHETIC CANDIDATES','demo')],btn(`Shortlist (${state.shortlist.length})`,'viewShortlist')+btn('Export Ranking','exportCandidates'));
  const viewport=`<div class="science-3d dark" data-tour="antibody-view" style="height:500px"><canvas id="moleculeCanvas" aria-label="Interactive antibody HA structural schematic"></canvas><div class="science-3d-toolbar"><div class="science-3d-title">MEDI8852–HA · 3D ${badge('STRUCTURAL SCHEMATIC','dark')}</div><div class="science-3d-actions"><button class="science-3d-btn" id="molAuto">Auto Rotate</button><button class="science-3d-btn" id="molRepresentation">Surface</button><button class="science-3d-btn" id="molInterface">Interface</button><button class="science-3d-btn" id="molReset">Reset Camera</button></div></div><div class="science-3d-caption">${state.lang==='cn'?`拖动旋转 · 滚轮缩放。项目背景：MEDI8852 scFv–H1N1 HA。晶体参考：PDB ${ref.pdb}，MEDI8852 Fab–H5 HA，${ref.method}，分辨率 ${ref.resolution}。当前 WebGL 几何图为具有真实景深交互的科学结构示意，并非原子级坐标渲染。`:`Drag to rotate · wheel to zoom. Project context: MEDI8852 scFv–H1N1 HA. Crystal reference metadata: PDB ${ref.pdb}, MEDI8852 Fab–H5 HA, ${ref.method}, ${ref.resolution}. The WebGL geometry is a scientific structural schematic with depth-aware interaction; it is not an atom-level coordinate rendering.`}</div><div class="science-3d-legend"><span><i class="science-3d-dot" style="background:#55B7A7"></i>MEDI8852 Fab/scFv context</span><span><i class="science-3d-dot" style="background:#5D8EAD"></i>Influenza HA trimer</span><span><i class="science-3d-dot" style="background:#C88A57"></i>Stem interface</span></div></div><div class="struct-meta-strip"><div class="struct-meta"><span>Project context</span><b>H1N1 HA · PDB 1RUZ template</b></div><div class="struct-meta"><span>Crystal reference</span><b>PDB ${ref.pdb} · H5 HA</b></div><div class="struct-meta"><span>Reference method</span><b>${ref.method}</b></div><div class="struct-meta"><span>Resolution</span><b>${ref.resolution}</b></div></div><div class="reference-callout"><b>${state.lang==='cn'?'科学边界。':'Scientific boundary.'}</b> ${state.lang==='cn'?`实验解析的 ${ref.pdb} 复合物仅作为结构参考背景。当前提供的 FluBlockers H1N1 对接总结没有包含经验证的坐标文件，因此离线画布始终明确标记为结构示意。`:`The experimentally solved ${ref.pdb} complex is used only as structural reference context. The supplied FluBlockers H1N1 docking summary did not include validated coordinate files, so the offline canvas remains explicitly schematic.`}</div>`;
  return `<div class="page">${head}<div class="three-col"><div class="sticky-side">${panel('Design Controls','Multi-objective engineering',objectiveControls())}</div>${panel('Molecular Workspace','Interactive academic structural context',viewport)}<div class="sticky-side">${panel('Design Candidates','Live re-ranking from deterministic demo metrics',candidateCards(),'','candidate-panel')}</div></div><div style="margin-top:18px">${panel('Design Analysis','Reference evidence + live calculations',antibodyBottom())}</div></div>`;
}

function circuitPlot(){const W=760,H=300,pad={l:45,r:25,t:20,b:35};const xs=t=>pad.l+(t-25)/(55-25)*(W-pad.l-pad.r);const ys=v=>H-pad.b-v*(H-pad.t-pad.b);const temps=Array.from({length:61},(_,i)=>25+i*.5);const orig=temps.map(t=>[xs(t),ys(calibrationResponse(t,{midpoint:50,slope:.34,constraintTemp:30,influence:0}))]);const cal=temps.map(t=>[xs(t),ys(calibrationResponse(t,{midpoint:50,slope:.34,constraintTemp:30,influence:state.calibrationInfluence}))]);const path=pts=>'M'+pts.map(p=>p.map(x=>x.toFixed(1)).join(',')).join(' L');return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}">${[0,.25,.5,.75,1].map(v=>`<line class="chart-grid" x1="${pad.l}" x2="${W-pad.r}" y1="${ys(v)}" y2="${ys(v)}"/><text class="chart-label" x="${pad.l-9}" y="${ys(v)+3}" text-anchor="end">${v.toFixed(2)}</text>`).join('')}<rect x="${xs(28)}" y="${pad.t}" width="${xs(32)-xs(28)}" height="${H-pad.t-pad.b}" fill="#B66D91" opacity=".08"/><line x1="${xs(50)}" x2="${xs(50)}" y1="${pad.t}" y2="${H-pad.b}" stroke="#4E7898" stroke-dasharray="4 4"/><path d="${path(orig)}" class="chart-line" stroke="#4E7898" stroke-dasharray="5 4"/><path d="${path(cal)}" class="chart-line" stroke="#2F8C83"/><circle cx="${xs(30)}" cy="${ys(.48)}" r="5" fill="#B66D91" class="chart-marker"/><text class="chart-label" x="${xs(30)+7}" y="${ys(.48)-7}">Experimental expression change ~30°C</text><text class="chart-label" x="${xs(50)-4}" y="${pad.t+11}" text-anchor="end">Predicted structural transition ~50°C</text>${[25,30,37,42,50,55].map(t=>`<text class="chart-label" x="${xs(t)}" y="${H-11}" text-anchor="middle">${t}°</text>`).join('')}</svg>`}
function renderCircuitContent(){
  if(state.circuitTab==='structure') return `<div class="rna-structure-grid"><div class="science-3d" style="height:390px"><canvas id="rnaFoldCanvas" aria-label="3D RNA folding schematic"></canvas><div class="science-3d-toolbar rna-toolbar"><div class="rna-toolbar-left"><div class="science-3d-title">3D RNA Fold</div>${badge('SCHEMATIC','warning rna-status-badge')}</div><div class="science-3d-actions"><button class="science-3d-btn" id="rnaAuto">Auto Rotate</button><button class="science-3d-btn" id="rnaReset">Reset Camera</button></div></div><div class="science-3d-caption">${state.lang==='cn'?`温度响应结构示意 · ${state.circuitTemp}°C。随着温度升高，碱基配对连接逐步减弱并趋向来源总结中的高温解链状态。`:`Temperature-responsive structural schematic · ${state.circuitTemp}°C. Base-pair contacts progressively weaken toward the high-temperature source-summary state.`}</div></div><div class="rna-evidence-stack"><div class="evidence-card"><div class="eyebrow">37°C · RNAFOLD</div><div class="evidence-value">Structured</div><div class="evidence-note">Source-summary low-temperature interpretation. Validated dot-bracket coordinates were not supplied.</div></div><div class="evidence-card"><div class="eyebrow">50°C · RNAFOLD</div><div class="evidence-value">Unfolding</div><div class="evidence-note">Major structural transition predicted near ~50°C in the project summary.</div></div><div class="evidence-card"><div class="eyebrow">CURRENT VIEW</div><div class="evidence-value mono">${state.circuitTemp}°C</div><div class="evidence-note">Interactive 3D morphology interpolates between schematic states; it is not a live RNAfold calculation.</div>${badge('MODELING DEMO','demo')}</div></div></div>`;
  if(state.circuitTab==='evidence') return `<div class="evidence-grid"><div class="evidence-card"><div class="eyebrow">MODEL</div><div class="evidence-value mono">~50°C</div><div class="evidence-note">Predicted RNA structural transition · RNAfold.</div>${badge('COMPUTATIONAL','source')}</div><div class="evidence-card"><div class="eyebrow">EXPERIMENT</div><div class="evidence-value mono">~30°C</div><div class="evidence-note">Observed expression-level change. Different readout.</div>${badge('EXPERIMENTAL','experimental')}</div><div class="evidence-card"><div class="eyebrow">ASSESSMENT</div><div class="evidence-value">Discrepancy</div><div class="evidence-note">Do not interpret as a simple 20°C prediction error.</div>${badge('MODEL GAP','warning')}</div></div><div style="margin-top:16px">${['Species Context|E. coli assumptions may not transfer directly to Lactobacillus.','Static Thermodynamics|Minimum-energy structures do not capture dynamic trajectories.','Folding Dynamics|Kinetic pathways and intermediate states are not represented.'].map(x=>{const[a,b]=x.split('|');return `<div class="limit-card"><b>${a}</b><p>${b}</p></div>`}).join('')}</div>`;
  if(state.circuitTab==='calibration') return `<div class="chart-title-row"><div><div class="panel-title">Model–Experiment Alignment</div><div class="panel-sub">Phenomenological recalibration sandbox</div></div>${badge('MODELING DEMO','demo')}</div>${circuitPlot()}<div class="objective"><div class="objective-head"><strong>Experimental influence</strong><span class="mono">${Math.round(state.calibrationInfluence*100)}%</span></div><input id="calibrationSlider" type="range" min="0" max="1" step="0.02" value="${state.calibrationInfluence}" style="width:100%"></div><div class="tiny muted">The teal curve illustrates constraint-driven model movement. It is not a completed FluBlockers calibration result.</div>`;
  return `<div class="grid grid-3">${[['Model RNA Folding Kinetics','Extend beyond static minimum-energy structures to temperature-dependent trajectories.'],['Include Intermediate States','Represent transient structures between low- and high-temperature states.'],['Apply Experimental Constraints','Use wet-lab expression observations to constrain the next model iteration.']].map((x,i)=>`<div class="evidence-card"><div class="eyebrow">0${i+1}</div><h4>${x[0]}</h4><p class="small muted">${x[1]}</p></div>`).join('')}</div><div style="margin-top:14px">${btn(state.circuitUpdate?'Added to DBTL':'Create DBTL Update','addCircuitUpdate',state.circuitUpdate?'':'primary')}</div>`;
}
function renderCircuit(){const tabs=['structure','evidence','calibration','recommend'];const names={structure:'Structure',evidence:'Evidence',calibration:'Calibration',recommend:'Design Recommendation'};const head=pageHeader('Regulatory Circuit Lab','Compare RNA-thermometer predictions with experimental observations and explore model recalibration.','比较 RNA 温度传感器结构预测与实验现象，并探索实验约束下的模型修正。',[badge('RNA THERMOMETER','source'),badge('RNAFOLD MODEL','source'),badge('MODEL DISCREPANCY','warning'),badge('OFFLINE','live')],btn('Export Analysis','exportCircuit'));
  const setup=`<div class="meta-grid"><dt>Regulatory element</dt><dd>RNA Thermometer</dd><dt>Host chassis</dt><dd>Lactobacillus</dd><dt>Prediction tool</dt><dd>RNAfold</dd><dt>Sequence</dt><dd>Not supplied</dd></div><div class="divider"></div><div class="objective-head"><strong>Temperature</strong><span class="mono">${state.circuitTemp}°C</span></div><input id="circuitTemp" type="range" min="25" max="55" step="1" value="${state.circuitTemp}" style="width:100%"><div style="display:flex;gap:5px;margin-top:8px"><button class="btn small tempPreset" data-temp="30">30°C</button><button class="btn small tempPreset" data-temp="37">37°C</button><button class="btn small tempPreset" data-temp="50">50°C</button></div><div class="divider"></div>${badge('SCHEMATIC STRUCTURES','warning')}`;
  const evidence=`<div class="meta-grid"><dt>Prediction</dt><dd>~50°C structural</dd><dt>Experiment</dt><dd>~30°C expression</dd><dt>Readout relation</dt><dd>Different</dd><dt>Status</dt><dd>Needs refinement</dd></div><div class="divider"></div><div class="eyebrow">PROVENANCE</div>${badge('FLUBLOCKERS SOURCE','source')} ${badge('MODELING DEMO','demo')}`;
  return `<div class="page">${head}<div class="three-col"><div class="sticky-side">${panel('Circuit Setup','RNA thermometer context',setup)}</div>${panel('Regulatory Modeling Workspace','Model → evidence → recalibration → next design',`<div class="tabbar">${tabs.map(t=>`<button class="tab ${state.circuitTab===t?'active':''}" data-circuit-tab="${t}">${names[t]}</button>`).join('')}</div><div style="margin-top:14px">${renderCircuitContent()}</div>`)}${panel('Evidence Inspector','Scientific boundary and provenance',evidence,'','sticky-side')}</div></div>`;
}

const EPIDEMIC_PRESET={days:180,dt:.25,N:1_000_000,initial:{S:999800,E:100,I:70,A:30,R:0},beta:.743,k:.55,gamma:.14,omega:1/2.2,p:.35};
function currentEpi(){return simulateSEIAR({...EPIDEMIC_PRESET,intervention:state.intervention,coverage:state.coverage})}
function linePath(data,key,W,H,pad,maxY){const x=d=>pad.l+d.day/EPIDEMIC_PRESET.days*(W-pad.l-pad.r);const y=v=>H-pad.b-v/maxY*(H-pad.t-pad.b);return 'M'+data.map(d=>`${x(d).toFixed(1)},${y(d[key]).toFixed(1)}`).join(' L')}
function epiChart(mode='impact'){
  const curr=currentEpi(),base=simulateSEIAR({...EPIDEMIC_PRESET,intervention:'none',coverage:0});const W=850,H=360,pad={l:54,r:25,t:22,b:38};const datasets=mode==='dynamics'?[['S','#8796A6'],['E','#C7924A'],['I','#C6534B'],['A','#6D719C'],['R','#2B8D68']]:[['I','#C6534B']];const maxY=mode==='dynamics'?EPIDEMIC_PRESET.N:Math.max(...base.trajectory.map(d=>d.I))*1.08;const y=v=>H-pad.b-v/maxY*(H-pad.t-pad.b);const xDay=d=>pad.l+d/EPIDEMIC_PRESET.days*(W-pad.l-pad.r);
  return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}">${[0,.25,.5,.75,1].map(v=>`<line class="chart-grid" x1="${pad.l}" x2="${W-pad.r}" y1="${y(maxY*v)}" y2="${y(maxY*v)}"/><text class="chart-label" x="${pad.l-8}" y="${y(maxY*v)+3}" text-anchor="end">${mode==='dynamics'?Math.round(100*v)+'%':Math.round(maxY*v/1000)+'k'}</text>`).join('')}${[0,30,60,90,120,150,180].map(d=>`<text class="chart-label" x="${xDay(d)}" y="${H-13}" text-anchor="middle">${d}</text>`).join('')}${mode==='impact'?`<path d="${linePath(base.trajectory,'I',W,H,pad,maxY)}" class="chart-line" stroke="#A9B3BF" stroke-dasharray="5 4"/>`:''}${datasets.map(([k,c])=>`<path d="${linePath(curr.trajectory,k,W,H,pad,maxY)}" class="chart-line" stroke="${c}"/>`).join('')}<circle cx="${xDay(curr.metrics.peakDay)}" cy="${y(curr.metrics.peakI)}" r="5" fill="#C6534B" class="chart-marker"/><text class="chart-label" x="${xDay(curr.metrics.peakDay)+8}" y="${y(curr.metrics.peakI)-8}">Peak ${fmt(curr.metrics.peakI,0)} · day ${fmt(curr.metrics.peakDay,0)}</text></svg>`;
}
function coverageChart(){const sweep=coverageSweep({...EPIDEMIC_PRESET,intervention:state.intervention},Array.from({length:21},(_,i)=>i/20));const W=850,H=340,pad={l:55,r:25,t:20,b:38};const max=Math.max(...sweep.map(x=>x.peakI))*1.05;const x=c=>pad.l+c*(W-pad.l-pad.r);const y=v=>H-pad.b-v/max*(H-pad.t-pad.b);const path='M'+sweep.map(p=>`${x(p.coverage).toFixed(1)},${y(p.peakI).toFixed(1)}`).join(' L');return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}"><rect class="coverage-band" x="${x(.3)}" y="${pad.t}" width="${x(.5)-x(.3)}" height="${H-pad.t-pad.b}"/><text class="chart-label" x="${(x(.3)+x(.5))/2}" y="${pad.t+12}" text-anchor="middle">30–50% source-reported range</text>${[0,.25,.5,.75,1].map(v=>`<line class="chart-grid" x1="${pad.l}" x2="${W-pad.r}" y1="${y(max*v)}" y2="${y(max*v)}"/>`).join('')}<path d="${path}" class="chart-line" stroke="#1E6A7A"/>${sweep.map(p=>`<circle cx="${x(p.coverage)}" cy="${y(p.peakI)}" r="3.5" fill="#1E6A7A"/>`).join('')}${[0,.2,.4,.6,.8,1].map(v=>`<text class="chart-label" x="${x(v)}" y="${H-12}" text-anchor="middle">${Math.round(v*100)}%</text>`).join('')}</svg>`}
function renderEpidemicSurface(){const res=currentEpi();return `<div><div class="science-3d" style="height:420px"><canvas id="epidemicSurfaceCanvas" aria-label="3D epidemic intervention impact surface"></canvas><div class="science-3d-toolbar"><div class="science-3d-title">3D Impact Surface ${badge('LIVE MODEL','live')}</div><div class="science-3d-actions"><button class="science-3d-btn" id="epi3dAuto">Auto Rotate</button><button class="science-3d-btn" id="epi3dReset">Reset Camera</button></div></div><div class="science-3d-caption">${state.lang==='cn'?'覆盖率 × 时间 × 感染负荷。曲面数值由浏览器端 SEIAR 引擎在当前干预与演示参数预设下实时重新计算。':'Coverage × time × infectious burden. Surface values are recomputed from the browser SEIAR engine under the current intervention and demo parameter preset.'}</div><div class="science-3d-axis x">Time →</div><div class="science-3d-axis z">Coverage</div><div class="science-3d-axis y">Infectious burden</div><div class="science-3d-legend"><span><i class="science-3d-dot" style="background:#5FAFC0"></i>Low burden</span><span><i class="science-3d-dot" style="background:#B96C55"></i>High burden</span><span class="contour-key">Contours · 20/40/60/80%</span></div></div><div class="surface-summary"><div><span>Current intervention</span><b>${state.intervention==='none'?'Baseline':state.intervention==='medi8852'?'MEDI8852':state.intervention==='1g01'?'1G01':'Combined'}</b></div><div><span>Current coverage</span><b>${Math.round(state.coverage*100)}%</b></div><div><span>Peak symptomatic</span><b>${fmt(res.metrics.peakI,0)}</b></div></div></div>`}
function renderEpiTab(){const res=currentEpi(),base=simulateSEIAR({...EPIDEMIC_PRESET,intervention:'none',coverage:0});if(state.epidemicTab==='dynamics') return epiChart('dynamics');if(state.epidemicTab==='impact')return `${epiChart('impact')}<div class="chart-legend"><span><i class="legend-line" style="background:#A9B3BF"></i>Baseline symptomatic</span><span><i class="legend-line" style="background:#B96C55"></i>Current scenario</span></div>`;if(state.epidemicTab==='coverage')return coverageChart();if(state.epidemicTab==='surface')return renderEpidemicSurface();return `<div class="compartment"><div class="comp-box"><b>S</b><span>Susceptible</span></div><span class="arrow">→ β</span><div class="comp-box"><b>E</b><span>Exposed</span></div><span class="arrow">→ ω</span><div class="comp-box"><b>I / A</b><span>Symptomatic / asymptomatic</span></div><span class="arrow">→ γ</span><div class="comp-box"><b>R</b><span>Recovered</span></div></div><div class="disclosure"><b>TriOmeFlow Simulation Equations.</b> The browser engine uses a standard SEIAR equation template consistent with source-defined compartments and parameter semantics. It is not presented as the verbatim original FluBlockers equation system because the original model code was not supplied.</div>`}
function epiControls(){const scenario=[['none','No Intervention','Baseline'],['medi8852','MEDI8852','β ↓ · k ↓'],['1g01','1G01','γ ↑'],['combined','Combined','β ↓ · k ↓ · γ ↑']];return `<div><div class="eyebrow">INTERVENTION STRATEGY</div>${scenario.map(s=>`<div class="scenario-card ${state.intervention===s[0]?'active':''}" data-intervention="${s[0]}"><b class="small">${s[1]}</b><div class="mechanism"><span class="mech-pill">${s[2]}</span>${s[0]!=='none'&&s[0]!=='combined'?badge('SOURCE MECHANISM','source'):''}</div></div>`).join('')}<div class="divider"></div><div class="objective-head"><strong>Intervention coverage</strong><span class="mono">${Math.round(state.coverage*100)}%</span></div><input id="coverageSlider" type="range" min="0" max="1" step="0.01" value="${state.coverage}" style="width:100%"><div class="source-range" style="--coverage:${state.coverage*100}%"><span class="marker"></span></div><div class="tiny muted">30–50% = source-reported intervention range; values outside are scenario extrapolation.</div><div class="divider"></div><details><summary class="small" style="cursor:pointer;font-weight:600">Advanced demo parameters</summary><div class="meta-grid"><dt>β</dt><dd class="mono">0.743</dd><dt>k</dt><dd class="mono">0.55</dd><dt>γ</dt><dd class="mono">0.14</dd><dt>ω</dt><dd class="mono">0.455</dd><dt>p</dt><dd class="mono">0.35</dd></div><div style="margin-top:7px">${badge('DEMO PRESET','demo')}</div></details><div style="margin-top:12px">${btn('Run Simulation','runEpidemic','primary')} ${btn('Reset','resetEpidemic')}</div></div>`}
function renderEpidemic(){const res=currentEpi(),base=simulateSEIAR({...EPIDEMIC_PRESET,intervention:'none',coverage:0});const reduction=(1-res.metrics.cumulative/base.metrics.cumulative)*100;const tabs=['impact','dynamics','coverage','surface','compartments'],names={impact:'Intervention',dynamics:'Dynamics',coverage:'Coverage Sweep',surface:'3D Impact Surface',compartments:'Compartments'};const head=pageHeader('Influenza Epidemic Twin','Simulate how antibody-mediated interventions reshape SEIAR transmission dynamics at the population level.','基于 SEIAR 仓室模型模拟抗体干预对流感传播、感染峰值与传播规模的影响。',[badge('SEIAR','source'),badge('LIVE SIMULATION','live'),badge('LOCAL RK4','live'),badge('FLUBLOCKERS-ANCHORED','source')],btn(state.savedScenario?'Scenario Saved':'Save Scenario','saveScenario')+btn('Export Trajectory','exportTrajectory'));
  const kpis=`<div class="grid grid-4" data-tour="epidemic-kpi">${kpi('Reference R₀','≈ 4.47','FluBlockers model fit','blue')}${kpi('Scenario R',res.metrics.scenarioR.toFixed(2),'TriOmeFlow live simulation','probiotic')}${kpi('Peak Symptomatic',fmt(res.metrics.peakI,0),`Day ${fmt(res.metrics.peakDay,0)}`,'virus')}${kpi('Cumulative Infections',fmt(res.metrics.cumulative,0),`${reduction>=0?'−':'+'}${Math.abs(reduction).toFixed(1)}% vs baseline`,'host')}</div>`;
  return `<div class="page">${head}${kpis}<div class="two-col-main" style="margin-top:18px"><div class="sticky-side">${panel('Scenario Setup','Reference mechanism + demo numerical preset',epiControls())}</div>${panel('SEIAR Simulation Workspace','Browser-side deterministic ODE simulation',`<div class="tabbar">${tabs.map(t=>`<button class="tab ${state.epidemicTab===t?'active':''}" data-epidemic-tab="${t}">${names[t]}</button>`).join('')}</div><div style="margin-top:12px" data-tour="epidemic-chart">${renderEpiTab()}</div>`,'')}</div></div>`;
}

function evidenceMatrix(){const epi=state.epidemicScenario||currentEpi().metrics;return `<table class="sci-table"><thead><tr><th>Evidence</th><th>Scale</th><th>Type</th><th>Status</th><th>Provenance</th></tr></thead><tbody><tr><td>MEDI8852 ΔG / Kd</td><td>Molecular</td><td>Computational</td><td>Favorable</td><td>${badge('FLUBLOCKERS','source')}</td></tr><tr><td>Gompertz growth fit</td><td>Cellular</td><td>Computational</td><td>Best fit</td><td>${badge('FLUBLOCKERS','source')}</td></tr><tr><td>RNA response</td><td>Regulatory</td><td>Model + Experiment</td><td>${badge('DISCREPANCY','warning')}</td><td>${badge('FLUBLOCKERS','source')}</td></tr><tr><td>${state.savedScenario?'Saved EP scenario':'Current EP scenario'}</td><td>Population</td><td>Simulation</td><td>Available</td><td>${badge('LIVE','live')}</td></tr>${state.shortlist.length?`<tr><td>${state.shortlist.length} shortlisted candidates</td><td>Molecular</td><td>Synthetic design</td><td>Exploratory</td><td>${badge('DEMO','demo')}</td></tr>`:''}</tbody></table>`}
function dbtlStageContent(){
 if(state.dbtlStage==='design')return `<div class="grid grid-2"><div class="evidence-card"><div class="eyebrow">ANTIBODY DESIGN</div><h4>MEDI8852-WT</h4><p class="small muted">Reference candidate · computationally favorable binding.</p>${badge('FLUBLOCKERS','source')}${state.shortlist.map(c=>`<div class="divider"></div><b class="small">${c}</b><p class="tiny muted">Synthetic exploratory candidate from Antibody Studio.</p>${badge('DEMO','demo')}`).join('')}</div><div class="evidence-card"><div class="eyebrow">REGULATORY DESIGN</div><h4>RNA Thermometer</h4><p class="small muted">Model issue: predicted structural transition ~50°C vs experimental expression change ~30°C (different readouts).</p>${badge('NEEDS UPDATE','warning')}</div></div>`;
 if(state.dbtlStage==='build')return `<div class="grid grid-3"><div class="evidence-card"><div class="eyebrow">CHASSIS</div><h4>Engineered LGG</h4><p class="small muted">Cellular implementation context.</p></div><div class="evidence-card"><div class="eyebrow">GROWTH</div><div class="evidence-value">Gompertz</div><p class="tiny muted">Best fit among Logistic / Gompertz / Richards.</p>${badge('FLUBLOCKERS','source')}</div><div class="evidence-card"><div class="eyebrow">EXPRESSION BURDEN</div><h4>Reduced growth</h4><p class="tiny muted">WT LGG max OD ≈ 3.0; recombinant strains reported slower / lower maximum OD.</p>${badge('FLUBLOCKERS','source')}</div></div>`;
 if(state.dbtlStage==='test')return evidenceMatrix();
 return `<div class="decision-board" data-tour="dbtl-decision"><div class="decision-col"><div class="decision-head">SUPPORTED</div><div class="decision-item"><h5>MEDI8852–HA interaction</h5><p>ΔG ≈ −11.4 kcal/mol · Kd ≈ 6.8 nM.</p><div class="priority medium">SOURCE-SUPPORTED COMPUTATIONAL</div></div></div><div class="decision-col"><div class="decision-head">UNCERTAIN</div><div class="decision-item"><h5>RNA thermometer behavior</h5><p>Prediction and experiment use different readouts and disagree in transition region.</p><div class="priority high">CONFLICT / DISCREPANCY</div></div></div><div class="decision-col"><div class="decision-head">ACTION REQUIRED</div><div class="decision-item"><h5>Refine regulatory model</h5><p>Include folding kinetics, intermediate states and experiment-constrained recalibration.</p><div class="priority high">HIGH PRIORITY</div></div><div class="decision-item"><h5>Validate growth burden</h5><p>Further characterize expression burden and plasmid stability.</p><div class="priority medium">MEDIUM</div></div></div></div>`;
}
function generateQueue(){return [
  {id:'Q1',title:'Refine RNA thermometer model',priority:'HIGH',reason:'Model–experiment discrepancy',source:'source'},
  {id:'Q2',title:'Retain MEDI8852 as reference',priority:'MEDIUM',reason:'Favorable predicted binding',source:'source'},
  {id:'Q3',title:'Characterize growth burden',priority:'MEDIUM',reason:'Recombinant strain growth reduction',source:'source'},
  ...(state.shortlist.length?[{id:'Q4',title:`Explore ${state.shortlist[0]}`,priority:'LOW',reason:'Synthetic shortlist context',source:'demo'}]:[])
]}
function dbtlQueue(){const q=state.dbtlQueue.length?state.dbtlQueue:generateQueue();return `<div data-tour="dbtl-queue">${q.map((x,i)=>`<div class="queue-item"><span class="queue-num">${String(i+1).padStart(2,'0')}</span><div><h5>${x.title}</h5><p>${x.reason}</p></div><div>${badge(x.priority,x.priority==='HIGH'?'warning':'')} ${x.source==='demo'?badge('DEMO','demo'):''}</div></div>`).join('')}</div><div style="padding:12px">${btn('Generate Next Design Queue','generateQueue','primary')} ${btn(`Create Cycle #0${state.cycle+1}`,'createCycle')}</div>`}
function renderDBTL(){const stages=[['design','Design',`${state.shortlist.length||1} items`],['build','Build','3 evidence'],['test','Test','4 observations'],['learn','Learn','2 decisions']];const head=pageHeader('Research DBTL Workspace','Connect computational design, engineering evidence, experimental feedback and model learning into the next research cycle.','将计算设计、工程菌构建证据、实验反馈与模型更新连接到下一轮研究决策。',[badge(`CYCLE #0${state.cycle}`,''),badge('CROSS-SCALE',''),badge('SESSION LINKED','live'),badge('DEMO WORKSPACE','demo')],btn('Reset Cycle','resetDbtl')+btn('Export Cycle','exportCycle'));
 const rail=`<div class="dbtl-rail">${stages.map(s=>`<div class="stage-item ${state.dbtlStage===s[0]?'active':''}" data-dbtl-stage="${s[0]}"><div class="stage-top"><span class="stage-name">${s[1]}</span><span class="stage-state">${s[0]==='learn'?'● active':'✓'}</span></div><div class="stage-sub">${s[2]}</div></div>`).join('')}</div><div class="divider"></div><div class="eyebrow">CROSS-SCALE STATUS</div><ul class="list-clean"><li><span class="status-dot green"></span>Molecular · Supported</li><li><span class="status-dot orange"></span>Cellular · Validate</li><li><span class="status-dot purple"></span>Regulatory · Discrepancy</li><li><span class="status-dot blue-dot"></span>Population · Scenario</li></ul>`;
 return `<div class="page">${head}<div class="grid grid-4">${kpi('Evidence Items','5','3 source-derived · 2 simulation/demo','blue')}${kpi('Open Questions','2','RNA mismatch · growth burden','host')}${kpi('Design Candidates',String(state.shortlist.length||3),'Reference + exploratory demo','probiotic')}${kpi('Next Cycle',state.dbtlCreated?'Ready':'72%','Workflow readiness only','virus')}</div><div class="three-col" style="margin-top:18px"><div class="sticky-side">${panel('Cycle Navigator','Design → Build → Test → Learn',rail)}</div>${panel((state.dbtlStage[0].toUpperCase()+state.dbtlStage.slice(1))+' Workspace','Evidence-backed research orchestration',dbtlStageContent())}${panel('Next Design Queue','Deterministic rule-based actions',dbtlQueue(),'','sticky-side')}</div><div class="mini-grid">${panel('Evidence Timeline','Session-linked activity',`<div class="timeline">${state.runs.slice(-5).reverse().map(r=>`<div class="time-item"><b class="mono">${r.id}</b><p>${r.module} · ${r.action||'completed'}</p></div>`).join('')||'<div class="time-item"><b>Workspace initialized</b><p>Run scientific modules to populate this timeline.</p></div>'}</div>`)}${panel('Evidence Matrix','Scale · type · status · provenance',evidenceMatrix())}</div></div>`;
}

function methodsContent(){const search=state.registrySearch.toLowerCase();if(state.methodsTab==='methods'){const items=methodSearchMatches(search);if(!items.length)return `<div class="registry-empty"><b>${state.lang==='cn'?'未找到匹配结果':'No matches found'}</b><span>${state.lang==='cn'?'请尝试方法名称、尺度或用途关键词。':'Try a method name, scale, or purpose keyword.'}</span></div>`;return `<div class="method-grid">${items.map(m=>`<div class="method-card ${search?'search-hit':''}" data-method="${m.id}"><div style="display:flex;justify-content:space-between;gap:6px"><h4>${m.name}</h4>${badge(m.execution,m.execution==='Live'?'live':'')}</div><p>${tr(m.purpose)}</p><div>${badge(m.source,m.source.includes('DEMO')?'demo':'source')} <span class="tiny muted">${tr(m.scale)}</span></div></div>`).join('')}</div>`}
 if(state.methodsTab==='data')return `<table class="sci-table"><thead><tr><th>Dataset</th><th>Source</th><th>Version</th><th>Status</th><th>Hash</th></tr></thead><tbody><tr><td>FluBlockers Demo Omics</td><td>${badge('TRIOMEFLOW DEMO','demo')}</td><td class="mono">1.0.0</td><td>Validated</td><td class="mono">deterministic</td></tr><tr><td>Antibody Candidate Library</td><td>${badge('TRIOMEFLOW DEMO','demo')}</td><td class="mono">1.0.0</td><td>Validated</td><td class="mono">deterministic</td></tr><tr><td>SEIAR Demo Preset</td><td>${badge('TRIOMEFLOW DEMO','demo')}</td><td class="mono">1.0.0</td><td>Validated</td><td class="mono">deterministic</td></tr>${state.omicsUserData?`<tr><td>${esc(state.omicsUserData.name)}</td><td>${badge('USER DATA','live')}</td><td>session</td><td>Validated</td><td class="mono">${state.omicsUserData.hash.slice(0,12)}…</td></tr>`:''}</tbody></table>`;
 if(state.methodsTab==='runs')return `<table class="sci-table"><thead><tr><th>Run ID</th><th>Module</th><th>Mode</th><th>Action</th><th>Runtime</th></tr></thead><tbody>${state.runs.length?state.runs.slice().reverse().map(r=>`<tr><td class="mono">${r.id}</td><td>${r.module}</td><td>${badge(r.mode,r.mode==='Live'?'live':r.mode==='Demo'?'demo':'')}</td><td>${r.action||'Analysis'}</td><td class="mono">${r.runtime||'—'}</td></tr>`).join(''):`<tr><td colspan="5" class="muted">No session runs yet. Scientific actions will register here.</td></tr>`}</tbody></table>`;
 if(state.methodsTab==='sources')return `<div class="method-grid">${SOURCES.map(s=>`<div class="method-card"><div style="display:flex;justify-content:space-between"><h4>${s.id}</h4>${badge(s.strength,s.strength==='SUMMARY'?'source':'demo')}</div><p><b>${s.title}</b><br>${tr(s.note)}</p><div class="tiny muted">${tr('Type')} · ${tr(s.type)}</div></div>`).join('')}</div><div class="disclosure"><b>Source limitation.</b> The supplied FluBlockers project summary itself notes that some content may have been AI-generated. Key claims should be verified against original model code, raw data or experimental records before being treated as primary evidence.</div>`;
 return `<div>${ASSUMPTIONS.map(a=>`<div class="assumption-card"><div style="display:flex;justify-content:space-between;gap:8px"><h4 data-i18n-lock>${a.id} · ${a.title}</h4><span>${badge(a.level,a.level.includes('DEMO')||a.level==='SYNTHETIC'?'demo':'warning')} ${badge(a.status,'')}</span></div><p>${tr(a.detail)}</p></div>`).join('')}</div>`;
}
function renderMethods(){const tabs=[['methods','Methods Registry'],['data','Data Registry'],['runs','Run Registry'],['sources','Source Ledger'],['assumptions','Assumption Ledger']];const head=pageHeader('Methods & Provenance Registry','Trace methods, datasets, assumptions and computational outputs across the FluBlockers workspace.','统一记录 TriOmeFlow 中的方法、数据来源、模型假设、运行参数和结果追溯信息。',[badge('METHOD REGISTRY',''),badge('PROVENANCE AWARE','source'),badge('OFFLINE REPRODUCIBLE','live'),badge('NO NETWORK DEPENDENCY','live')],btn('Export Methods','exportMethods')+btn('Export Manifest','exportManifest','primary'));
 const summary=`<div class="grid grid-4">${kpi('Source-derived','12','Registry facts','blue')}${kpi('Live computations','6','Browser-side methods','probiotic')}${kpi('Synthetic assets','5','Explicit demo inputs','host')}${kpi('Open assumptions',String(ASSUMPTIONS.length),'Tracked limitations','virus')}</div>`;
 return `<div class="page">${head}${summary}<div class="panel" style="margin-top:18px"><div class="registry-tabs">${tabs.map(t=>`<button class="registry-tab ${state.methodsTab===t[0]?'active':''}" data-methods-tab="${t[0]}">${t[1]}</button>`).join('')}</div><div class="panel-body"><div class="registry-toolbar"><div class="registry-search-shell"><input class="search-input" id="registrySearch" placeholder="Search registry…" value="${esc(state.registrySearch)}"><span class="registry-search-note">${state.methodsTab==='methods'?(state.registrySearch?(state.lang==='cn'?`${methodSearchMatches(state.registrySearch).length} 个匹配`:`${methodSearchMatches(state.registrySearch).length} matches`):(state.lang==='cn'?'支持方法名称 / 尺度 / 用途搜索':'Search method name / scale / purpose')):''}</span></div>${badge('TriOmeFlow v1.0.0','')} ${badge('Demo Data v1.2.0','demo')}</div>${methodsContent()}</div></div><div class="disclosure"><b>Scientific Disclosure.</b> TriOmeFlow is an offline computational research prototype. Source-derived project results, live browser calculations, precomputed analyses and synthetic demonstration data are explicitly distinguished throughout the workspace. Synthetic demonstration outputs should not be interpreted as experimentally validated biological findings.</div></div>`;
}

function renderPage(){switch(state.route){case'overview':return renderOverview();case'tri-omics':return renderTriOmics();case'workflow':return renderWorkflow();case'antibody':return renderAntibody();case'circuit':return renderCircuit();case'epidemic':return renderEpidemic();case'dbtl':return renderDBTL();case'methods':return renderMethods();default:return renderOverview()}}
function renderApp(){stop3DAnimations();document.getElementById('app').innerHTML=shell(renderPage());applyI18n(document.getElementById('app'));bindGlobal();bindPage();requestAnimationFrame(initScientific3D);if(state.route==='workflow') requestAnimationFrame(()=>{bindWorkflowDrag();const t=document.getElementById('workflowTerminal');if(t)t.scrollTop=t.scrollHeight});if(state.tour)requestAnimationFrame(applyTourHighlight)}

function bindGlobal(){
  document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();state.route=el.dataset.route;state.inspector=null;persist();history.replaceState(null,'','#'+state.route);renderApp()}));
  document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.lang!==state.lang)setState({lang:el.dataset.lang})}));
  document.getElementById('startTour')?.addEventListener('click',startTour);
  document.getElementById('globalExport')?.addEventListener('click',exportManifest);
  document.getElementById('workspaceSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter')performWorkspaceSearch(e.target.value)});
}
function bindPage(){
  document.querySelectorAll('[data-inspect]').forEach(el=>el.addEventListener('click',()=>{state.inspector={type:'system',id:el.dataset.inspect};persist();renderApp()}));
  document.querySelectorAll('[data-system]').forEach(el=>el.addEventListener('click',()=>{state.inspector={type:'system',id:el.dataset.system};persist();renderApp()}));
  document.getElementById('resetWorkspace')?.addEventListener('click',resetWorkspace);document.getElementById('mapReset')?.addEventListener('click',()=>setState({inspector:null}));document.getElementById('tourOverview')?.addEventListener('click',startTour);document.getElementById('exportSummary')?.addEventListener('click',exportSummary);
  // Workflow Studio
  document.querySelectorAll('[data-add-workflow]').forEach(el=>el.addEventListener('click',()=>addWorkflowNode(el.dataset.addWorkflow)));
  document.querySelectorAll('[data-wf-node]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();state.workflowSelected=el.dataset.wfNode;persist();renderApp()}));
  document.getElementById('wfNodeName')?.addEventListener('change',e=>updateWorkflowSelected({name:e.target.value}));
  document.getElementById('wfNodeImage')?.addEventListener('change',e=>updateWorkflowSelected({image:e.target.value}));
  document.getElementById('wfNodeCpu')?.addEventListener('change',e=>updateWorkflowSelected({cpu:Number(e.target.value)}));
  document.getElementById('wfNodeRam')?.addEventListener('change',e=>updateWorkflowSelected({ram:Number(e.target.value)}));
  document.getElementById('resetWorkflow')?.addEventListener('click',resetWorkflow);document.getElementById('exportWorkflow')?.addEventListener('click',exportWorkflow);document.getElementById('runWorkflow')?.addEventListener('click',runWorkflowPipeline);
  // Omics
  document.querySelectorAll('[data-omics-tab]').forEach(el=>el.addEventListener('click',()=>setState({omicsTab:el.dataset.omicsTab})));
  document.querySelectorAll('[data-node]').forEach(el=>el.addEventListener('click',()=>{state.inspector={type:'omics',id:el.dataset.node};persist();renderApp()}));
  document.getElementById('networkThreshold')?.addEventListener('change',e=>setState({omicsThreshold:Number(e.target.value)},{render:true}));
  document.getElementById('networkSearch')?.addEventListener('change',e=>{const q=e.target.value.toLowerCase();const n=OMICS_NODES.find(n=>n.label.toLowerCase().includes(q)||n.id.toLowerCase()===q);if(n)setState({inspector:{type:'omics',id:n.id},omicsFocus:n.id});else toast('Entity not found','warning')});
  document.getElementById('focusNode')?.addEventListener('click',()=>{const id=state.inspector?.type==='omics'?state.inspector.id:null;setState({omicsFocus:state.omicsFocus?null:id});});
  document.getElementById('fitNetwork')?.addEventListener('click',()=>setState({omicsFocus:null}));document.getElementById('loadOmics')?.addEventListener('click',()=>{setState({omicsUserData:null});toast('FluBlockers demo dataset loaded','success')});document.getElementById('exportOmics')?.addEventListener('click',()=>downloadCsv('triomeflow-features.csv',OMICS_NODES.map(n=>({feature:n.id,domain:n.domain,effect:n.effect,fdr:n.fdr,source:n.provenance}))));
  document.getElementById('runOmics')?.addEventListener('click',runOmics);document.getElementById('omicsUpload')?.addEventListener('change',handleOmicsUpload);
  document.querySelectorAll('[data-pathway]').forEach(el=>el.addEventListener('click',()=>{const p=PATHWAYS.find(x=>x.name===el.dataset.pathway);if(p){state.omicsFocus=p.features[0];state.inspector={type:'omics',id:p.features[0]};state.omicsTab='network';persist();renderApp();toast(`${p.name}: related network features highlighted`,'success')}}));
  // Antibody
  document.querySelectorAll('.objective-slider').forEach(el=>el.addEventListener('change',e=>{state.weights=normalizeWeights({...state.weights,[e.target.dataset.weight]:Number(e.target.value)},e.target.dataset.weight);persist();renderApp()}));
  document.querySelectorAll('[data-candidate]').forEach(el=>el.addEventListener('click',()=>{state.selectedCandidate=el.dataset.candidate;state.inspector={type:'candidate',id:el.dataset.candidate};persist();renderApp()}));
  document.querySelectorAll('[data-shortlist]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();const id=el.dataset.shortlist;state.shortlist=state.shortlist.includes(id)?state.shortlist.filter(x=>x!==id):[...state.shortlist,id];persist();renderApp();toast(state.shortlist.includes(id)?'Candidate added to DBTL shortlist':'Candidate removed','success')}));
  document.querySelectorAll('[data-antibody-tab]').forEach(el=>el.addEventListener('click',()=>setState({antibodyTab:el.dataset.antibodyTab})));
  document.getElementById('rerank')?.addEventListener('click',()=>{registerRun('AB','Antibody Studio','Live','Candidate re-ranking','12 ms');toast('Candidate ranking recalculated','success')});
  document.getElementById('toggleShortlist')?.addEventListener('click',()=>{const id=state.selectedCandidate;state.shortlist=state.shortlist.includes(id)?state.shortlist.filter(x=>x!==id):[...state.shortlist,id];persist();renderApp();toast(state.shortlist.includes(id)?'Candidate added to DBTL shortlist':'Candidate removed','success')});
  document.getElementById('viewShortlist')?.addEventListener('click',()=>{state.route='dbtl';state.dbtlStage='design';persist();renderApp()});document.getElementById('exportCandidates')?.addEventListener('click',exportCandidates);
  document.getElementById('langmuirSlider')?.addEventListener('change',e=>setState({langmuirConcentration:Number(e.target.value)}));
  // Circuit
  document.querySelectorAll('[data-circuit-tab]').forEach(el=>el.addEventListener('click',()=>setState({circuitTab:el.dataset.circuitTab})));
  document.getElementById('circuitTemp')?.addEventListener('change',e=>setState({circuitTemp:Number(e.target.value)}));document.querySelectorAll('.tempPreset').forEach(el=>el.addEventListener('click',()=>setState({circuitTemp:Number(el.dataset.temp)})));
  document.getElementById('calibrationSlider')?.addEventListener('change',e=>{state.calibrationInfluence=Number(e.target.value);persist();renderApp()});document.getElementById('addCircuitUpdate')?.addEventListener('click',()=>{state.circuitUpdate=true;registerRun('RC','Circuit Lab','Demo','Model update added','9 ms');persist();renderApp();toast('Circuit model update added to DBTL','success')});document.getElementById('exportCircuit')?.addEventListener('click',()=>downloadJson('circuit-analysis.json',{source:{predictedStructuralTransition:'~50°C',experimentalExpressionChange:'~30°C',readoutsDifferent:true},demoCalibration:{influence:state.calibrationInfluence}}));
  // Epidemic
  document.querySelectorAll('[data-intervention]').forEach(el=>el.addEventListener('click',()=>setState({intervention:el.dataset.intervention})));
  document.getElementById('coverageSlider')?.addEventListener('change',e=>{state.coverage=Number(e.target.value);persist();renderApp()});document.querySelectorAll('[data-epidemic-tab]').forEach(el=>el.addEventListener('click',()=>setState({epidemicTab:el.dataset.epidemicTab})));
  document.getElementById('runEpidemic')?.addEventListener('click',runEpidemic);document.getElementById('resetEpidemic')?.addEventListener('click',()=>setState({intervention:'none',coverage:0,epidemicScenario:null,savedScenario:false}));document.getElementById('saveScenario')?.addEventListener('click',saveScenario);document.getElementById('exportTrajectory')?.addEventListener('click',exportTrajectory);
  // DBTL
  document.querySelectorAll('[data-dbtl-stage]').forEach(el=>el.addEventListener('click',()=>setState({dbtlStage:el.dataset.dbtlStage})));
  document.getElementById('generateQueue')?.addEventListener('click',()=>{state.dbtlQueue=generateQueue();registerRun('DBTL','DBTL Loop','Live','Next design queue generated','8 ms');persist();renderApp();toast(`${state.dbtlQueue.length} prioritized actions generated`,'success')});document.getElementById('createCycle')?.addEventListener('click',()=>{state.cycle+=1;state.dbtlCreated=true;state.dbtlStage='design';state.dbtlQueue=[];registerRun('DBTL','DBTL Loop','Live',`Cycle #0${state.cycle} created`,'7 ms');persist();renderApp();toast(`DBTL Cycle #0${state.cycle} created`,'success')});document.getElementById('resetDbtl')?.addEventListener('click',()=>setState({dbtlStage:'learn',cycle:3,dbtlQueue:[],dbtlCreated:false}));document.getElementById('exportCycle')?.addEventListener('click',exportCycle);
  // Methods
  document.querySelectorAll('[data-methods-tab]').forEach(el=>el.addEventListener('click',()=>setState({methodsTab:el.dataset.methodsTab})));
  document.getElementById('registrySearch')?.addEventListener('change',e=>{state.registrySearch=e.target.value;persist();renderApp()});document.getElementById('registrySearch')?.addEventListener('keydown',e=>{if(e.key==='Enter'){state.registrySearch=e.target.value;persist();renderApp()}});document.getElementById('exportManifest')?.addEventListener('click',exportManifest);document.getElementById('exportMethods')?.addEventListener('click',exportMethods);
  document.querySelectorAll('[data-method]').forEach(el=>el.addEventListener('click',()=>{const m=METHODS.find(x=>x.id===el.dataset.method);if(m)showModal(m.name,`<div class="meta-grid"><dt>Scale</dt><dd>${m.scale}</dd><dt>Origin</dt><dd>${m.origin}</dd><dt>Execution</dt><dd>${m.execution}</dd><dt>Purpose</dt><dd>${m.purpose}</dd><dt>Source</dt><dd>${m.source}</dd></div>`)}));
}

function runOmics(){registerRun('OM','Tri-Omics','Hybrid','Cross-domain analysis','2.4 s');const btnEl=document.getElementById('runOmics');if(btnEl){btnEl.disabled=true;btnEl.textContent='Building network…';setTimeout(()=>{state.omicsTab='network';persist();renderApp();toast('Demo analysis completed · advanced results are precomputed','success')},700)}}
async function handleOmicsUpload(e){const file=e.target.files?.[0];if(!file)return;const text=await file.text();const rows=parseCsvText(text);const val=validateLongFormatCsv(rows);if(!val.valid){showModal('Dataset validation failed',`<ul class="list-clean">${val.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="tiny muted">Expected columns: sample_id, feature_id, value, optional group.</div>`);return}const hash=await sha256(text);state.omicsUserData={name:file.name,samples:rows.length,hash};registerRun('OM','Tri-Omics','Live','User CSV validation','18 ms');persist();renderApp();toast('User dataset validated locally','success')}
async function sha256(text){
  if(globalThis.crypto?.subtle){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('')}
  const K=[
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  const rotr=(x,n)=>(x>>>n)|(x<<(32-n));
  const input=Array.from(new TextEncoder().encode(String(text))); const bitLen=input.length*8;
  input.push(0x80); while((input.length%64)!==56) input.push(0);
  const hi=Math.floor(bitLen/0x100000000), lo=bitLen>>>0;
  for(let i=3;i>=0;i--) input.push((hi>>>(i*8))&255); for(let i=3;i>=0;i--) input.push((lo>>>(i*8))&255);
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  for(let off=0;off<input.length;off+=64){const w=new Uint32Array(64);for(let i=0;i<16;i++){const j=off+i*4;w[i]=((input[j]<<24)|(input[j+1]<<16)|(input[j+2]<<8)|input[j+3])>>>0}for(let i=16;i<64;i++){const s0=(rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>>3))>>>0;const s1=(rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>>10))>>>0;w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0}let [a,b,c,d,e,f,g,h]=H;for(let i=0;i<64;i++){const S1=(rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;const ch=((e&f)^((~e)&g))>>>0;const t1=(h+S1+ch+K[i]+w[i])>>>0;const S0=(rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;const maj=((a&b)^(a&c)^(b&c))>>>0;const t2=(S0+maj)>>>0;h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0}H=[(H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,(H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0]}
  return H.map(x=>x.toString(16).padStart(8,'0')).join('');
}

function runEpidemic(){const t=performance.now();const res=currentEpi();const runtime=`${Math.max(1,Math.round(performance.now()-t))} ms`;state.epidemicScenario={...res.metrics,intervention:state.intervention,coverage:state.coverage};registerRun('EP','Epidemic Twin','Live','SEIAR simulation',runtime);persist();renderApp();toast(`Simulation completed · population conservation passed`,'success')}
function saveScenario(){state.epidemicScenario={...currentEpi().metrics,intervention:state.intervention,coverage:state.coverage};state.savedScenario=true;registerRun('EP','Epidemic Twin','Live','Scenario saved','3 ms');persist();renderApp();toast('Scenario linked to DBTL','success')}
function registerRun(prefix,module,mode,action,runtime){const n=state.runs.filter(r=>r.prefix===prefix).length+1;state.runs.push({id:`${prefix}-${String(n).padStart(3,'0')}`,prefix,module,mode,action,runtime,status:'Completed',at:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})});if(state.runs.length>50)state.runs=state.runs.slice(-50);persist()}

const VIEW3D={raf:new Set(),states:{}};
function stop3DAnimations(){for(const id of VIEW3D.raf)cancelAnimationFrame(id);VIEW3D.raf.clear()}
function viewState(key,defaults={}){if(!VIEW3D.states[key])VIEW3D.states[key]={yaw:-.45,pitch:.25,zoom:1,auto:false,...defaults};return VIEW3D.states[key]}
function rotate3D(p,cam){let{x,y,z}=p;const cy=Math.cos(cam.yaw),sy=Math.sin(cam.yaw);[x,z]=[x*cy-z*sy,x*sy+z*cy];const cp=Math.cos(cam.pitch),sp=Math.sin(cam.pitch);[y,z]=[y*cp-z*sp,y*sp+z*cp];return{x,y,z}}
function project3D(p,cam,W,H,scale=1){const r=rotate3D(p,cam),depth=3.05+r.z*.14;const f=(Math.min(W,H)*.61*cam.zoom*scale)/Math.max(1.9,depth);return{x:W/2+r.x*f,y:H/2-r.y*f,z:r.z,f}}
function setupCanvas(canvas){const rect=canvas.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);return{ctx,W:rect.width,H:rect.height}}
function bindOrbit(canvas,key,draw,defaults={}){const cam=viewState(key,defaults);let dragging=false,lastX=0,lastY=0;const redraw=()=>draw(canvas,cam);canvas.addEventListener('pointerdown',e=>{dragging=true;cam.auto=false;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;cam.yaw+=(e.clientX-lastX)*.009;cam.pitch=Math.max(-1.25,Math.min(1.25,cam.pitch+(e.clientY-lastY)*.007));lastX=e.clientX;lastY=e.clientY;redraw()});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);canvas.addEventListener('wheel',e=>{e.preventDefault();cam.zoom=Math.max(.62,Math.min(1.85,cam.zoom*(e.deltaY>0?.92:1.08)));redraw()},{passive:false});const loop=()=>{if(!document.body.contains(canvas))return;if(cam.auto){cam.yaw+=.0032;redraw()}const id=requestAnimationFrame(loop);VIEW3D.raf.add(id)};redraw();const id=requestAnimationFrame(loop);VIEW3D.raf.add(id);return{cam,redraw}}
function drawSoftGrid(ctx,W,H,dark=false){ctx.save();ctx.strokeStyle=dark?'rgba(126,169,190,.07)':'rgba(75,117,132,.08)';ctx.lineWidth=1;for(let x=0;x<W;x+=34){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=34){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore()}
function line3D(ctx,pts,cam,W,H,color,width=2,alpha=1){const ps=pts.map(p=>project3D(p,cam,W,H));ctx.save();ctx.strokeStyle=color;ctx.globalAlpha=alpha;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ps.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.stroke();ctx.restore();return ps}
function sphere2D(ctx,p,r,color,alpha=1){ctx.save();const g=ctx.createRadialGradient(p.x-r*.35,p.y-r*.4,r*.1,p.x,p.y,r);g.addColorStop(0,'#FFFFFF');g.addColorStop(.18,color);g.addColorStop(1,color+'22');ctx.globalAlpha=alpha;ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill();ctx.restore()}
function manifoldPoint(n,i){const bases={Host:[-1.25,.45,.15],Probiotic:[.85,-.45,.1],Metabolite:[.15,-.95,-.55],Virus:[1.15,.65,.35]};const b=bases[n.domain];const a=(i+1)*1.47;return{x:b[0]+Math.cos(a)*(.24+n.centrality*.12),y:b[1]+Math.sin(a*.8)*.34,z:b[2]+Math.sin(a)*.42+n.effect*.08}}
function drawOmicsManifold(canvas,cam){const{ctx,W,H}=setupCanvas(canvas);ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#FBFDFD');bg.addColorStop(1,'#EEF5F6');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);drawSoftGrid(ctx,W,H,false);const colors={Host:'#6D719C',Probiotic:'#2F8C83',Metabolite:'#557B8F',Virus:'#B96C55'};const pts=OMICS_NODES.map(manifoldPoint);OMICS_EDGES.forEach(e=>{const ai=OMICS_NODES.findIndex(n=>n.id===e.source),bi=OMICS_NODES.findIndex(n=>n.id===e.target);if(ai<0||bi<0)return;line3D(ctx,[pts[ai],pts[bi]],cam,W,H,e.type==='negative'?'#9A7F86':'#89AAB3',Math.abs(e.association)*2,.35)});const rendered=pts.map((p,i)=>({p:project3D(p,cam,W,H),n:OMICS_NODES[i]})).sort((a,b)=>a.p.z-b.p.z);rendered.forEach(({p,n})=>{const r=5+n.centrality*5;sphere2D(ctx,p,r,colors[n.domain],.95);ctx.fillStyle='#425865';ctx.font='10px Inter,system-ui';ctx.fillText(n.label,p.x+r+5,p.y+3)});ctx.fillStyle='#7B8B94';ctx.font='9px Inter,system-ui';ctx.fillText(state.lang==='cn'?'潜变量 1':'Latent 1',W-58,H-12);ctx.fillText(state.lang==='cn'?'潜变量 2':'Latent 2',10,16)}
function initOmics3D(){const c=document.getElementById('omicsManifoldCanvas');if(!c)return;const ctrl=bindOrbit(c,'omics',drawOmicsManifold,{yaw:-.55,pitch:.32,zoom:1,auto:true});document.getElementById('manifoldAuto')?.addEventListener('click',e=>{ctrl.cam.auto=!ctrl.cam.auto;e.currentTarget.textContent=tr(ctrl.cam.auto?'Pause':'Auto Rotate')});document.getElementById('manifoldReset')?.addEventListener('click',()=>{Object.assign(ctrl.cam,{yaw:-.55,pitch:.32,zoom:1,auto:false});ctrl.redraw()})}
function haMonomer(angle){const pts=[];for(let i=0;i<46;i++){const t=i/45,rad=.34+.08*Math.sin(t*Math.PI*3),a=angle+.18*Math.sin(t*Math.PI*2);pts.push({x:Math.cos(a)*rad,y:-1.25+t*1.75,z:Math.sin(a)*rad})}for(let i=1;i<34;i++){const t=i/33,a=angle+t*Math.PI*1.8;pts.push({x:Math.cos(a)*(.34+.52*Math.sin(t*Math.PI)),y:.5+.72*Math.sin(t*Math.PI),z:Math.sin(a)*(.34+.52*Math.sin(t*Math.PI))})}return pts}
function antibodyChains(){const heavy=[],light=[];for(let i=0;i<55;i++){const t=i/54;heavy.push({x:-1.45+.92*t+.13*Math.sin(t*9),y:.95-.65*t+.18*Math.sin(t*5),z:.18+.18*Math.cos(t*7)});light.push({x:-1.35+.82*t+.11*Math.sin(t*8+1.2),y:.72-.52*t+.15*Math.sin(t*4+1),z:-.08+.2*Math.cos(t*6+1)})}return[heavy,light]}
function drawMolecule3D(canvas,cam){const{ctx,W,H}=setupCanvas(canvas);ctx.clearRect(0,0,W,H);const bg=ctx.createRadialGradient(W*.45,H*.42,10,W*.5,H*.48,Math.max(W,H)*.72);bg.addColorStop(0,'#12384D');bg.addColorStop(.52,'#0A2738');bg.addColorStop(1,'#061822');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);drawSoftGrid(ctx,W,H,true);const ha=[];for(let k=0;k<3;k++)ha.push(haMonomer(k*Math.PI*2/3+.2));const headCenters=[];for(let k=0;k<3;k++){const a=k*Math.PI*2/3+.2;headCenters.push({x:Math.cos(a)*.48,y:.83,z:Math.sin(a)*.48})}headCenters.map(p=>project3D(p,cam,W,H)).sort((a,b)=>a.z-b.z).forEach((p,i)=>sphere2D(ctx,p,29,['#5F91AF','#56849F','#6A9AB6'][i],.28));ha.forEach((chain,i)=>line3D(ctx,chain,cam,W,H,['#5F91AF','#56849F','#6A9AB6'][i],5.4,.92));const core=project3D({x:0,y:-.32,z:0},cam,W,H);sphere2D(ctx,core,19,'#507C96',.22);const abs=antibodyChains();const abDomains=[{x:-1.25,y:.82,z:.18},{x:-.86,y:.55,z:.10},{x:-1.14,y:.62,z:-.12},{x:-.73,y:.4,z:-.04}];abDomains.map(p=>project3D(p,cam,W,H)).sort((a,b)=>a.z-b.z).forEach((p,i)=>sphere2D(ctx,p,18-i*1.5,i%2?'#68BDB0':'#55B7A7',.32));abs.forEach((chain,i)=>line3D(ctx,chain,cam,W,H,i?'#72C5B8':'#55B7A7',6.0,.96));const stem=[{x:-.53,y:.3,z:.12},{x:-.35,y:.05,z:.02},{x:-.18,y:-.12,z:-.02}];line3D(ctx,stem,cam,W,H,'#C88A57',cam.interface?10:5,cam.interface?1:.78);for(let i=0;i<9;i++){const p=project3D({x:-.43+i*.035,y:.19-i*.034,z:.05+Math.sin(i*.9)*.035},cam,W,H);sphere2D(ctx,p,cam.interface?5.4:3.6,'#C88A57',cam.interface?1:.84)}ctx.fillStyle='rgba(210,228,236,.78)';ctx.font='10px Inter,system-ui';ctx.fillText(state.lang==='cn'?'MEDI8852 结构示意 · 参考晶体背景 5JW4':'MEDI8852 structural schematic · crystal context 5JW4',16,H-16)}
function bindMolecule3D(){const c=document.getElementById('moleculeCanvas');if(!c)return;const ctrl=bindOrbit(c,'molecule',drawMolecule3D,{yaw:-.52,pitch:.18,zoom:1.02,auto:true,interface:false});document.getElementById('molAuto')?.addEventListener('click',e=>{ctrl.cam.auto=!ctrl.cam.auto;e.currentTarget.textContent=tr(ctrl.cam.auto?'Pause':'Auto Rotate')});document.getElementById('molInterface')?.addEventListener('click',()=>{ctrl.cam.interface=!ctrl.cam.interface;ctrl.redraw()});document.getElementById('molReset')?.addEventListener('click',()=>{Object.assign(ctrl.cam,{yaw:-.52,pitch:.18,zoom:1.02,auto:false,interface:false});ctrl.redraw()})}
function rnaGeometry(temp){const open=Math.max(0,Math.min(1,(temp-37)/13)),a=[],b=[],pairs=[];for(let i=0;i<34;i++){const t=i/33,ang=t*Math.PI*3.3;const sep=.32+open*(.45+.12*Math.sin(t*Math.PI));const bend=.55*Math.sin(t*Math.PI);const x=-1.08+t*2.16;const y=.38*Math.sin(ang)+bend*.22;const z=.34*Math.cos(ang);a.push({x,y:y+sep/2,z});b.push({x,y:y-sep/2,z:-z});if(i%3===0)pairs.push([a[a.length-1],b[b.length-1],1-open*.78])}for(let i=0;i<14;i++){const t=i/13,ang=t*Math.PI*1.2;const x=1.08+.48*Math.sin(ang),y=.58*Math.cos(ang)*(1-open*.45),z=.42*Math.sin(ang*1.6);a.push({x,y,z});b.push({x:x+.04,y:y-.06-open*.14,z:z-.08})}return{a,b,pairs,open}}
function drawRna3D(canvas,cam){const{ctx,W,H}=setupCanvas(canvas);ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#FAFCFD');bg.addColorStop(1,'#EEF5F6');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);drawSoftGrid(ctx,W,H,false);const g=rnaGeometry(state.circuitTemp);line3D(ctx,g.a,cam,W,H,'#4E7898',4.8,.93);line3D(ctx,g.b,cam,W,H,'#2F8C83',4.8,.93);g.pairs.forEach(([a,b,alpha])=>line3D(ctx,[a,b],cam,W,H,'#91A9B4',1.4,alpha));ctx.fillStyle='#677A86';ctx.font='10px Inter,system-ui';ctx.fillText((state.lang==='cn'?'当前温度 ':'Temperature ')+state.circuitTemp+'°C',16,H-16)}
function initRna3D(){const c=document.getElementById('rnaFoldCanvas');if(!c)return;const ctrl=bindOrbit(c,'rna',drawRna3D,{yaw:-.28,pitch:.25,zoom:1.05,auto:true});document.getElementById('rnaAuto')?.addEventListener('click',e=>{ctrl.cam.auto=!ctrl.cam.auto;e.currentTarget.textContent=tr(ctrl.cam.auto?'Pause':'Auto Rotate')});document.getElementById('rnaReset')?.addEventListener('click',()=>{Object.assign(ctrl.cam,{yaw:-.28,pitch:.25,zoom:1.05,auto:false});ctrl.redraw()})}
function epidemicSurfaceData(){const coverages=Array.from({length:21},(_,i)=>i/20),days=Array.from({length:25},(_,i)=>i*7.5);return coverages.map(c=>{const sim=simulateSEIAR({...EPIDEMIC_PRESET,intervention:state.intervention,coverage:c});return days.map(d=>{let row=sim.trajectory.reduce((best,r)=>Math.abs(r.day-d)<Math.abs(best.day-d)?r:best,sim.trajectory[0]);return{coverage:c,day:d,burden:row.I+row.A}})})}
function drawEpidemicSurface(canvas,cam){const{ctx,W,H}=setupCanvas(canvas);ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#FBFDFD');bg.addColorStop(1,'#EDF4F5');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);drawSoftGrid(ctx,W,H,false);const data=epidemicSurfaceData(),max=Math.max(...data.flat().map(p=>p.burden),1);const map=p=>({x:(p.day/180-.5)*2.25,y:(p.burden/max)*1.65-.7,z:(p.coverage-.5)*1.75});for(let r=0;r<data.length-1;r++)for(let c=0;c<data[r].length-1;c++){const cell=[map(data[r][c]),map(data[r+1][c]),map(data[r+1][c+1]),map(data[r][c+1])].map(p=>project3D(p,cam,W,H));const avg=(data[r][c].burden+data[r+1][c].burden+data[r+1][c+1].burden+data[r][c+1].burden)/(4*max);ctx.beginPath();ctx.moveTo(cell[0].x,cell[0].y);cell.slice(1).forEach(q=>ctx.lineTo(q.x,q.y));ctx.closePath();ctx.fillStyle=`rgba(${Math.round(79+avg*106)},${Math.round(154-avg*62)},${Math.round(171-avg*83)},${.12+avg*.28})`;ctx.fill();ctx.strokeStyle='rgba(70,112,127,.18)';ctx.lineWidth=.7;ctx.stroke()}data.forEach(row=>line3D(ctx,row.map(map),cam,W,H,'#7596A2',.8,.45));for(let c=0;c<data[0].length;c++)line3D(ctx,data.map(row=>map(row[c])),cam,W,H,'#86A6B1',.75,.42);ctx.fillStyle='#6D808B';ctx.font='9px Inter,system-ui';ctx.fillText(state.lang==='cn'?'时间 →':'Time →',W-55,H-12);ctx.fillText(state.lang==='cn'?'覆盖率':'Coverage',12,17)}
function initEpidemic3D(){const c=document.getElementById('epidemicSurfaceCanvas');if(!c)return;const ctrl=bindOrbit(c,'epidemic',drawEpidemicSurface,{yaw:-.66,pitch:.56,zoom:.92,auto:true});document.getElementById('epi3dAuto')?.addEventListener('click',e=>{ctrl.cam.auto=!ctrl.cam.auto;e.currentTarget.textContent=tr(ctrl.cam.auto?'Pause':'Auto Rotate')});document.getElementById('epi3dReset')?.addEventListener('click',()=>{Object.assign(ctrl.cam,{yaw:-.66,pitch:.56,zoom:.92,auto:false});ctrl.redraw()})}
function initScientific3D(){if(state.route==='tri-omics'&&state.omicsTab==='manifold')initOmics3D();if(state.route==='antibody')bindMolecule3D();if(state.route==='circuit'&&state.circuitTab==='structure')initRna3D();if(state.route==='epidemic'&&state.epidemicTab==='surface')initEpidemic3D()}

